const btn = document.getElementById('ai4a11y-spot-restore');
if (!btn) return !window.__ai4a11yReadingSpot?.enabled; // only before enable

if (btn.tagName !== 'BUTTON' || btn.type !== 'button') return false;
if (!btn.textContent.includes('Jump back to where you were')) return false;

const rect = btn.getBoundingClientRect();
if (rect.width < 24 || rect.height < 24) return false;

// Verify fixed position in viewport
const cs = window.getComputedStyle(btn);
if (cs.position !== 'fixed') return false;
return true;

const btn = document.getElementById('ai4a11y-spot-restore');
if (!btn) return !window.__ai4a11yReadingSpot?.enabled; // only before enable

btn.focus();
if (document.activeElement !== btn) return false;

const cs = window.getComputedStyle(btn);
const outlineWidth = parseFloat(cs.outlineWidth);
const hasOutline = cs.outlineStyle !== 'none' && outlineWidth >= 2;
const hasShadow = cs.boxShadow && cs.boxShadow !== 'none';
if (!hasOutline && !hasShadow) return false;

// Center of button is not covered by any overlay
const rect = btn.getBoundingClientRect();
const elAtCenter = document.elementFromPoint(rect.left + rect.width / 2, rect.top + rect.height / 2);
if (elAtCenter !== btn) return false;

btn.blur();
return true;

