const btn = document.getElementById('ai4a11y-spot-restore');
if (!btn) return !window.__ai4a11yReadingSpot?.enabled; // only before enable

btn.focus();
btn.click();

// Must scroll to the saved position (850)
if (window.scrollY !== 850) return false;

// Button should remove itself
if (document.getElementById('ai4a11y-spot-restore') !== null) return false;

// Focus should be placed on an element at the spot, not document.body
const active = document.activeElement;
if (!active || active === document.body) return false;

// Clean up focus and scroll at end of check
active.blur();
window.scrollTo(0, 0);
return true;
